window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8c2686c08b14a6fd"]={"versions": [{"id": "FIG-8c2686c08b14a6fd", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Feature-Modell / Feature-Dekompositionsbaum (FODA-Notation gemäß AUTOSAR Feature Modeling).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Foundation (<code>FO_TR_Features</code>, R24-11). Das Diagramm definiert die funktionale Dekomposition der plattformübergreifenden (Foundation, Classic Platform, Adaptive Platform) Entwicklungs- und Diagnoseinfrastruktur unterhalb der Standardisierungsdomäne <strong>Development</strong> (<code>FO_TR_FEAT_00111</code>).\n</li><li><strong>Zweck:</strong> Bereitstellung standardisierter Konzepte für Laufzeitbeobachtung, Messdatenerfassung, Parameteranpassung und Leistungsanalyse während des Entwicklungs- und Absicherungszyklus eines Steuergeräts (ECU / Machine).\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Wurzel-Feature (Parent):</strong>\n<ul class=\"fig-list\"><li><code>FO_TR_FEAT_00111</code>: <strong>Development</strong> – Übergreifendes Sammel-Feature für entwicklungsbegleitende Dienste, Schnittstellen und Tool-Interaktionen.\n</li></ul>\n</li><li><strong>Kind-Features (Sub-Features):</strong>\n<ol class=\"fig-list\"><li><code>FO_TR_FEAT_00120</code>: <strong>Measurement_and_Calibration</strong> – Laufzeitzugriff auf interne Variablen und Kalibrierparameter (typisch via XCP, A2L/ASAP2, RTE-Hooks, BSW-Interna).\n</li><li><code>FO_TR_FEAT_00117</code>: <strong>Debugging</strong> – Interaktive Fehlersuche, Haltepunkte, Registerinspektion und On-Chip-Debugger-Unterstützung (z. B. JTAG/CoreSight, Core-Dumps, Det/Exception-Handler).\n</li><li><code>FO_TR_FEAT_00112</code>: <strong>Logging</strong> – Strukturierte Protokollierung von Betriebs- und Diagnosedaten zur Laufzeit (z. B. Diagnostic Log and Trace [DLT], <code>ara::log</code> in AP).\n</li><li><code>FO_TR_FEAT_00115</code>: <strong>Tracing_and_Profiling</strong> – Nicht-invasive bzw. minimal-invasive Aufzeichnung von Eventfolgen, Funktionslaufzeiten und Stackauslastungen (z. B. über ARTI / AUTOSAR Run-Time Interface, Nexus, SystemView).\n</li><li><code>FO_TR_FEAT_00119</code>: <strong>Timing_Analysis</strong> – Erfassung und Validierung des zeitlichen Systemverhaltens (z. B. Task-Laufzeiten, Event-Ketten, Jitter, End-to-End-Latenzen gemäß AUTOSAR TIMEX).\n</li></ol>\n</li><li><strong>Beziehungssemantik &amp; Kardinalitäten:</strong>\n<ul class=\"fig-list\"><li><strong>Optionale Sub-Features:</strong> Alle fünf Kanten enden an den Kind-Elementen mit einem ungefüllten Kreis (<em>hollow circle</em>). Dies spezifiziert eine Kardinalität von <code>[0..1]</code> pro Sub-Feature relativ zum Parent-Feature.\n</li><li><strong>Unabhängige Kombinierbarkeit:</strong> Es liegen keine wechselseitigen Ausschlusskanten (XOR) oder erzwungenen Bündelungen (OR) vor; jedes Feature kann je nach Plattform-, Tool- und Projektanforderung unabhängig voneinander aktiviert oder ausgelassen werden.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\"><em>Da es sich um ein statisches Feature-Variabilitätsmodell handelt, existiert kein sequenzieller Kontrollfluss. Die funktionale Laufzeitkopplung der dekomponierten Features gliedert sich wie folgt:</em></p>\n<ol class=\"fig-list\"><li><strong>Instrumentierung &amp; Stimulierung:</strong> \n<ul class=\"fig-list\"><li>BSW/OS-Hooks und Compiler-Flags triggern synchron <code>Tracing_and_Profiling</code> sowie <code>Timing_Analysis</code>.\n</li><li>Applikationscode und BSW rufen über APIs synchron Logging-Schnittstellen (z. B. <code>Dlt_SendLogMessage</code> / <code>ara::log</code>) auf.\n</li></ul>\n</li><li><strong>Messung &amp; Parametrierung:</strong>\n<ul class=\"fig-list\"><li>Asynchrone XCP-DAQs/ODTs (<code>Measurement_and_Calibration</code>) tasten Variablen getriggert über OS-Raster (z. B. 1ms, 10ms) ab oder führen synchrone Parametermodifikationen über Page-Switching/Emulation aus.\n</li></ul>\n</li><li><strong>Trace- und Datenexport:</strong>\n<ul class=\"fig-list\"><li>Weiterleitung gepufferter Daten über Kommunikationsbusse (Ethernet/SOME/IP, CAN) oder dedizierte Traceschnittstellen an externe Kalibrier-/Timing-Tools.\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Plattform-Allokation:</strong>\n<ul class=\"fig-list\"><li><strong>Classic Platform (CP):</strong> Realisierung über BSW-Module wie <code>Xcp</code>, <code>Dlt</code>, <code>Det</code>, <code>Mcu</code> sowie OS-Hooks (<code>PreTaskHook</code>, <code>PostTaskHook</code>) und ARTI-Instrumentation.\n</li><li><strong>Adaptive Platform (AP):</strong> Realisierung primär über Functional Clusters (<code>ara::log</code>, ARTI/AP Execution Management Tracing, Core Dump Handling).\n</li></ul>\n</li><li><strong>Footprint &amp; Schedulability (SOP vs. DEV):</strong>\n<ul class=\"fig-list\"><li>Entwicklungs-Features verursachen signifikanten Speicher- (RAM/ROM) und Laufzeit-Overhead sowie Intrusion-Effekte (Probe-Effect).\n</li><li>Konfiguration muss über Pre-Compile-Schalter (<code>#define DLT_DEV_ERROR_DETECT STD_OFF</code>, Weglassen von XCP-Treibern) für Serien-Builds (SOP) vollständig deaktivierbar sein.\n</li></ul>\n</li><li><strong>Security &amp; Safety:</strong>\n<ul class=\"fig-list\"><li>Kalibrier-, Debugging- und Logging-Interfaces exponieren ECU-Interne. Für Serienstände müssen Hardware-Debug-Ports (JTAG/SWD) physisch/elektronisch gesperrt und Protokolle (<code>FO_TR_FEAT_00120</code>) durch Security Access (Seed &amp; Key) abgesichert werden.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-c5336c177608114a", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Feature-Modell / Feature-Dekompositionsbaum (FODA-Notation gemäß AUTOSAR Feature Modeling).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Foundation (<code>FO_TR_Features</code>, R24-11). Das Diagramm definiert die funktionale Dekomposition der plattformübergreifenden (Foundation, Classic Platform, Adaptive Platform) Entwicklungs- und Diagnoseinfrastruktur unterhalb der Standardisierungsdomäne <strong>Development</strong> (<code>FO_TR_FEAT_00111</code>).\n</li><li><strong>Zweck:</strong> Bereitstellung standardisierter Konzepte für Laufzeitbeobachtung, Messdatenerfassung, Parameteranpassung und Leistungsanalyse während des Entwicklungs- und Absicherungszyklus eines Steuergeräts (ECU / Machine).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Wurzel-Feature (Parent):</strong>\n<ul class=\"fig-list\"><li><code>FO_TR_FEAT_00111</code>: <strong>Development</strong> – Übergreifendes Sammel-Feature für entwicklungsbegleitende Dienste, Schnittstellen und Tool-Interaktionen.\n</li></ul>\n</li><li><strong>Kind-Features (Sub-Features):</strong>\n<ol class=\"fig-list\"><li><code>FO_TR_FEAT_00269</code>: <strong>Bus_Mirroring</strong> – Spiegelung von Buskommunikation (z. B. CAN, LIN, FlexRay, Ethernet) auf Diagnoseschnittstellen oder Logging-Ports zur externen Netzwerkanalyse.\n</li><li><code>FO_TR_FEAT_00263</code>: <strong>ECU_Data_Collection</strong> – Mechanismen zur zyklischen oder ereignisbasierten Erfassung und Aggregation interner Steuergerätezustände und Diagnosedaten.\n</li><li><code>FO_TR_FEAT_00117</code>: <strong>Debugging</strong> – Interaktive Fehlersuche, Haltepunkte, Registerinspektion und On-Chip-Debugger-Unterstützung (z. B. JTAG/CoreSight, Core-Dumps, Det/Exception-Handler).\n</li><li><code>FO_TR_FEAT_00112</code>: <strong>Logging</strong> – Strukturierte Protokollierung von Betriebs- und Diagnosedaten zur Laufzeit (z. B. Diagnostic Log and Trace [DLT], <code>ara::log</code> in AP).\n</li><li><code>FO_TR_FEAT_00115</code>: <strong>Tracing_and_Profiling</strong> – Nicht-invasive bzw. minimal-invasive Aufzeichnung von Eventfolgen, Funktionslaufzeiten und Stackauslastungen (z. B. über ARTI / AUTOSAR Run-Time Interface, Nexus, SystemView).\n</li><li><code>FO_TR_FEAT_00120</code>: <strong>Measurement_and_Calibration</strong> – Laufzeitzugriff auf interne Variablen und Kalibrierparameter (typisch via XCP, A2L/ASAP2, RTE-Hooks, BSW-Interna).\n</li></ol>\n</li><li><strong>Beziehungssemantik &amp; Kardinalitäten:</strong>\n<ul class=\"fig-list\"><li><strong>Optionale Sub-Features:</strong> Alle sechs Kanten enden an den Kind-Elementen mit einem ungefüllten Kreis (<em>hollow circle</em>). Dies spezifiziert eine Kardinalität von <code>[0..1]</code> pro Sub-Feature relativ zum Parent-Feature.\n</li><li><strong>Unabhängige Kombinierbarkeit:</strong> Es liegen keine wechselseitigen Ausschlusskanten (XOR) oder erzwungenen Bündelungen (OR) vor; jedes Feature kann je nach Plattform-, Tool- und Projektanforderung unabhängig voneinander aktiviert oder ausgelassen werden.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\"><em>Da es sich um ein statisches Feature-Variabilitätsmodell handelt, existiert kein sequenzieller Kontrollfluss. Die funktionale Laufzeitkopplung der dekomponierten Features gliedert sich wie folgt:</em></p>\n<ol class=\"fig-list\"><li><strong>Instrumentierung, Erfassung &amp; Stimulierung:</strong> \n<ul class=\"fig-list\"><li>BSW/OS-Hooks und Compiler-Flags triggern synchron <code>Tracing_and_Profiling</code>.\n</li><li>Interne Datenquellen und Scheduler initiieren die zyklische oder eventgetriebene Datenerfassung über <code>ECU_Data_Collection</code>.\n</li><li>Netzwerktreiber spiegeln empfangene oder gesendete Kommunikationsrahmen über <code>Bus_Mirroring</code> an dedizierte Analyseports.\n</li><li>Applikationscode und BSW rufen über APIs synchron Logging-Schnittstellen (z. B. <code>Dlt_SendLogMessage</code> / <code>ara::log</code>) auf.\n</li></ul>\n</li><li><strong>Messung &amp; Parametrierung:</strong>\n<ul class=\"fig-list\"><li>Asynchrone XCP-DAQs/ODTs (<code>Measurement_and_Calibration</code>) tasten Variablen getriggert über OS-Raster (z. B. 1ms, 10ms) ab oder führen synchrone Parametermodifikationen über Page-Switching/Emulation aus.\n</li></ul>\n</li><li><strong>Trace- und Datenexport:</strong>\n<ul class=\"fig-list\"><li>Weiterleitung gepufferter Mess-, Trace-, Spiegel- und Diagnosedaten über Kommunikationsbusse (Ethernet/SOME/IP, CAN) oder dedizierte Schnittstellen an externe Kalibrier-, Test- und Entwicklungstools.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Plattform-Allokation:</strong>\n<ul class=\"fig-list\"><li><strong>Classic Platform (CP):</strong> Realisierung über BSW-Module wie <code>Xcp</code>, <code>Dlt</code>, <code>Det</code>, <code>Mcu</code> sowie OS-Hooks (<code>PreTaskHook</code>, <code>PostTaskHook</code>) und ARTI-Instrumentation.\n</li><li><strong>Adaptive Platform (AP):</strong> Realisierung primär über Functional Clusters (<code>ara::log</code>, ARTI/AP Execution Management Tracing, Core Dump Handling).\n</li></ul>\n</li><li><strong>Footprint &amp; Schedulability (SOP vs. DEV):</strong>\n<ul class=\"fig-list\"><li>Entwicklungs-Features verursachen signifikanten Speicher- (RAM/ROM) und Laufzeit-Overhead sowie Intrusion-Effekte (Probe-Effect).\n</li><li>Konfiguration muss über Pre-Compile-Schalter (<code>#define DLT_DEV_ERROR_DETECT STD_OFF</code>, Weglassen von XCP-Treibern) für Serien-Builds (SOP) vollständig deaktivierbar sein.\n</li></ul>\n</li><li><strong>Security &amp; Safety:</strong>\n<ul class=\"fig-list\"><li>Kalibrier-, Debugging- und Logging-Interfaces exponieren ECU-Interne. Für Serienstände müssen Hardware-Debug-Ports (JTAG/SWD) physisch/elektronisch gesperrt und Protokolle (<code>FO_TR_FEAT_00120</code>) durch Security Access (Seed &amp; Key) abgesichert werden.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-8c2686c08b14a6fd", "to": "FIG-c5336c177608114a", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Kind-Feature <code>FO_TR_FEAT_00119</code> (<code>Timing_Analysis</code>) entfernt.\n</li><li>Kind-Feature <code>FO_TR_FEAT_00269</code> (<code>Bus_Mirroring</code>) als optionales Sub-Feature ergänzt.\n</li><li>Kind-Feature <code>FO_TR_FEAT_00263</code> (<code>ECU_Data_Collection</code>) als optionales Sub-Feature ergänzt.\n</li><li>Position von <code>FO_TR_FEAT_00120</code> (<code>Measurement_and_Calibration</code>) von der ersten Position links ganz nach rechts verlagert.\n</li></ul>"}]};
